using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.AI;
// Inject into the isolated build only. No Editor dependencies and no damage/HP/save editing.
public sealed class C1Probe:MonoBehaviour {
 [Serializable] public class Row{public string name,status,detail;}
 [Serializable]class Report{public string layer,mode,error;public Row[] rows;}
 [Serializable]class Expected{public string run,region,layout,streams,events,loot,gear,terrain,ledger,inventory;public int seed;public Vector3 position;}
 [Serializable]class RuntimeTrace{public string stage,target,mode;public Vector3 position,from,to;public float time,before,after;public int frame;}
 [Serializable]class Metric{public string status,scope;public int objects,colliders,enemies,materials;public double departureMilliseconds;}
 public static bool Done;public static int Code;public string Root;string mode;CombatSession s;readonly List<Row> rows=new List<Row>();
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Install(){if(!Environment.GetCommandLineArgs().Contains("-c1-probe"))return;var g=new GameObject("C1 isolated runtime probe");DontDestroyOnLoad(g);g.AddComponent<C1Probe>();}
 public void Check(string name,bool value,string detail=""){rows.Add(new Row{name=name,status=value?"PASS":"FAIL",detail=detail});File.AppendAllText(Root+"/progress.jsonl",JsonUtility.ToJson(rows.Last())+"\n");}
 public IEnumerator Wait(Func<bool> f,float sec){float end=Time.realtimeSinceStartup+sec;while(!f()&&Time.realtimeSinceStartup<end)yield return null;}
 IEnumerator Start(){Root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);mode=Environment.GetEnvironmentVariable("C1_MODE")??"explore";var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-c1-mode");if(i>=0)mode=args[i+1];Application.runInBackground=true;var stack=new Stack<IEnumerator>();stack.Push(Run());while(stack.Count>0){bool next;object value=null;try{next=stack.Peek().MoveNext();if(next)value=stack.Peek().Current;}catch(Exception e){Finish(e.ToString());yield break;}if(!next){stack.Pop();continue;}if(value is IEnumerator sub){stack.Push(sub);continue;}yield return value;}Finish(null);}
 IEnumerator Entry(){yield return Wait(()=>GameEntry.Instance!=null,20);var entry=GameEntry.Instance;if(entry==null)throw new Exception("No title");entry.Refresh();if(mode=="resume"){Check("actual-continue",entry.Info.canContinue&&entry.Continue());}else {entry.AskNew();Check("actual-new-confirm",entry.ConfirmNew());}yield return Wait(()=>UnityEngine.Object.FindFirstObjectByType<CombatSession>()?.Saves?.IsInitialized==true,35);s=UnityEngine.Object.FindFirstObjectByType<CombatSession>();if(s?.Saves?.IsInitialized!=true)throw new Exception("No initialized game: "+GameEntry.Error);s.hero.Inventory.SetOpen(false);s.hero.SaveMenuOpen=false;yield return null;PlayerInput.Focus(true);}
 void FreezeOthers(CombatEnemy keep=null){foreach(var e in s.enemies){if(e==keep)continue;e.enabled=false;var b=e.GetComponent<RuinsBossBrain>();if(b!=null)b.enabled=false;}}
 IEnumerator Depart(){var clock=System.Diagnostics.Stopwatch.StartNew();bool departed=s.Flow.DepartRuins();Check("actual-camp-departure",departed,s.Flow.Error+" / "+s.hero.Inventory.Notifications.Text);if(!departed)throw new Exception("Departure rollback: "+s.hero.Inventory.Notifications.Text);yield return Wait(()=>s.WorldReady&&s.Flow.ActiveRun!=null,20);clock.Stop();if(!s.WorldReady)throw new Exception("No ready ruins: "+s.Flow.Error);Check("zone-count",s.GetComponent<ForestRegionRuntime>().Layout.points.Length==RuinsLayout.DefaultStage);Check("run-map-bound",s.Flow.ActiveRun.region==RuinsLayout.Region&&s.Flow.ActiveRun.contentRevision==RuinsLayout.Content&&s.Flow.ActiveRun.generationVersion==9);Check("forest-supplement-not-retagged",!NewWeaponDrop.KnownRevision(s.Flow.ActiveRun.contentRevision));var root=s.GetComponent<ForestRegionRuntime>().PresentationRoot;File.WriteAllText(Root+"/scene-metrics.json",JsonUtility.ToJson(new Metric{status="MEASURED_COUNTS",scope="Actual scene counts and synchronous departure; CPU/GPU/DrawCalls/GC performance NOT_RUN",objects=root.GetComponentsInChildren<Transform>(true).Length,colliders=root.GetComponentsInChildren<Collider>(true).Length,enemies=s.enemies.Length,materials=root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Where(m=>m!=null).Distinct().Count(),departureMilliseconds=clock.Elapsed.TotalMilliseconds},true));}
 void Trace(string stage,string target="",float before=0,float after=0,Vector3 from=default,Vector3 to=default){File.AppendAllText(Root+"/runtime-trace.jsonl",JsonUtility.ToJson(new RuntimeTrace{stage=stage,target=target,mode=mode,position=s.hero.transform.position,time=Time.time,frame=Time.frameCount,before=before,after=after,from=from,to=to})+"\n");}
 IEnumerator Go(Vector3 goal,float max=35){var region=s.GetComponent<ForestRegionRuntime>();var path=new NavMeshPath();if(!NavMesh.SamplePosition(goal,out var end,2,NavMesh.AllAreas)||!NavMesh.SamplePosition(s.hero.transform.position,out var start,2,NavMesh.AllAreas)||!NavMesh.CalculatePath(start.position,end.position,NavMesh.AllAreas,path)||path.status!=NavMeshPathStatus.PathComplete)throw new Exception("Actual path unavailable: "+goal);int corner=1;float until=Time.realtimeSinceStartup+max;while(Vector3.ProjectOnPlane(s.hero.transform.position-end.position,Vector3.up).magnitude>.45f&&Time.realtimeSinceStartup<until&&!s.hero.Health.Dead){while(corner<path.corners.Length-1&&Vector3.ProjectOnPlane(path.corners[corner]-s.hero.transform.position,Vector3.up).magnitude<.6f)corner++;var delta=Vector3.ProjectOnPlane(path.corners[Mathf.Min(corner,path.corners.Length-1)]-s.hero.transform.position,Vector3.up);s.hero.GetComponent<CharacterController>().Move(Vector3.ClampMagnitude(delta,s.hero.moveSpeed*Time.deltaTime));if(Time.frameCount%20==0)Trace("actual-cc-move",from:start.position,to:end.position);yield return null;}bool ok=Vector3.ProjectOnPlane(s.hero.transform.position-end.position,Vector3.up).magnitude<.7f;Check("physical-walk-"+goal,ok,"NavMesh corners + actual CharacterController.Move; no teleport");if(!ok)throw new Exception("Movement blocked before "+goal+" at "+s.hero.transform.position);}
 WorldEventPoint Point(string id)=>s.Events.Points.Single(p=>p.entityId==id);
 IEnumerator Interact(string id){var p=Point(id);yield return Go(p.transform.position+Vector3.back*1.8f);yield return null;var resolver=s.hero.Inventory.Interactions;resolver.Refresh();var offer=resolver.E;Check("offered-"+id,offer?.targetId==id,offer?.targetId??"no offer");Check("interact-"+id,offer?.targetId==id&&resolver.Execute(offer),s.Flow.Error);}
 IEnumerator Shot(string name){yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Root+"/"+name,t.EncodeToPNG());Destroy(t);}
 string LootSignature()=>string.Join("|",UnityEngine.Object.FindObjectsByType<LootPickup>(FindObjectsSortMode.None).Where(l=>l.gameObject.scene==s.gameObject.scene&&!l.Collected).OrderBy(l=>l.InteractionId).Select(l=>l.InteractionId+":"+l.Amount+":"+l.Kind+":"+l.Gear?.id));
 string GearSignature()=>string.Join("|",s.hero.GetComponent<AdventureLoadout>().items.OrderBy(g=>g.id).Select(g=>JsonUtility.ToJson(g)));
 string TerrainSignature(){using(var sha=System.Security.Cryptography.SHA256.Create())using(var ms=new MemoryStream()){foreach(var t in s.GetComponent<ForestRegionRuntime>().PresentationRoot.GetComponentsInChildren<Terrain>().OrderBy(t=>t.transform.position.z).ThenBy(t=>t.transform.position.x)){var h=t.terrainData.GetHeights(0,0,257,257);var b=new byte[h.Length*4];Buffer.BlockCopy(h,0,b,0,b.Length);ms.Write(b,0,b.Length);var holes=t.terrainData.GetHoles(0,0,256,256);foreach(bool present in holes)ms.WriteByte(present?(byte)1:(byte)0);}return BitConverter.ToString(sha.ComputeHash(ms.ToArray())).Replace("-","");}}
 string Ledger(){var r=s.Flow.ActiveRun;return string.Join(",",r.broughtRemaining)+"|"+string.Join(",",r.earnedRemaining)+"|"+string.Join(",",s.Camp.Materials)+"|"+string.Join(",",s.Flow.Profile.badges.OrderBy(x=>x))+"|"+JsonUtility.ToJson(s.Flow.Profile.tutorial);}
 string InventorySignature()=>string.Join(",",Enumerable.Range(0,6).Select(i=>s.hero.Inventory.Count((MaterialKind)i)))+"|"+s.hero.Inventory.HealthPotionCount;
 void Package(){Check("actual-save-checkpoint",s.Saves.SaveProgress(false),s.Saves.FailureDetail);var run=s.Flow.ActiveRun;var expected=new Expected{run=run.runId,region=run.regionInstanceId,seed=run.seed,layout=JsonUtility.ToJson(s.GetComponent<ForestRegionRuntime>().Layout),streams=JsonUtility.ToJson(run.randomStreams),events=string.Join("|",s.Events.Points.OrderBy(p=>p.entityId).Select(p=>p.entityId+":"+p.Used)),loot=LootSignature(),gear=GearSignature(),position=s.hero.transform.position,terrain=TerrainSignature(),ledger=Ledger(),inventory=InventorySignature()};File.WriteAllText(Root+"/expected.json",JsonUtility.ToJson(expected,true));string dest=Root+"/SeedPackage";Directory.CreateDirectory(dest);foreach(var f in Directory.GetFiles(Path.GetDirectoryName(s.Saves.SavePath),"*",SearchOption.AllDirectories)){string relative=f.Substring(Path.GetDirectoryName(s.Saves.SavePath).Length).TrimStart(Path.DirectorySeparatorChar);string target=Path.Combine(dest,relative);Directory.CreateDirectory(Path.GetDirectoryName(target));File.Copy(f,target,false);}}
 IEnumerator Explore(){FreezeOthers();var region=s.GetComponent<ForestRegionRuntime>();var exploration=s.GetComponent<RuinsExploration>();Check("free-exit-initial",region.PathComplete(s.hero.transform.position,region.Layout.exits[0].position));Check("gate-real-block",!region.PathComplete(region.Layout.entry,region.Layout.points[2].position)&&Physics.Linecast(new Vector3(0,1,218),new Vector3(0,1,222)));s.hero.Inventory.SetOpen(true);Vector3 pos=s.hero.transform.position;yield return Wait(()=>false,.25f);Check("pause-real-stable",s.hero.transform.position==pos&&s.hero.GameplayPaused);s.hero.Inventory.SetOpen(false);yield return null;
  yield return Interact("c1:lever");Check("lever-no-repeat",!Point("c1:lever").Interact(s.hero));yield return Interact("c1:door");Check("gate-physical-open",exploration.DoorOpen&&!Physics.Linecast(new Vector3(0,1,218),new Vector3(0,1,222)));Check("all-main-zones-path",region.Layout.points.All(p=>region.PathComplete(region.Layout.entry,p.position)));yield return Shot("plaza-door.png");
  yield return Go(new Vector3(-2.6f,.1f,221.2f));Check("north-close-door",Point("c1:door").Interact(s.hero)&&!exploration.DoorOpen);bool northReopen=Point("c1:door").Interact(s.hero);Check("north-reopen-door",northReopen&&exploration.DoorOpen);if(!northReopen)throw new Exception("A real user can be trapped north of the closed door");yield return Go(new Vector3(-2.6f,.1f,216.2f));
  Check("close-door",Point("c1:door").Interact(s.hero)&&!exploration.DoorOpen);Check("closed-no-path",!region.PathComplete(region.Layout.entry,region.Layout.points[2].position));Check("reopen-door",Point("c1:door").Interact(s.hero)&&exploration.DoorOpen);
  yield return Interact("c1:plaza-chest");int ground=UnityEngine.Object.FindObjectsByType<LootPickup>().Count(l=>!l.Collected);Check("chest-real-ground",ground>=2);Check("chest-no-repeat",!Point("c1:plaza-chest").Interact(s.hero)&&ground==UnityEngine.Object.FindObjectsByType<LootPickup>().Count(l=>!l.Collected));
  yield return Interact("c1:archive");Check("secret-open",exploration.SecretOpen);yield return Interact("c1:hidden");yield return Shot("underground-hidden.png");
  var material=UnityEngine.Object.FindObjectsByType<LootPickup>().Where(l=>l.Gear==null&&!l.Collected&&l.gameObject.scene==s.gameObject.scene).OrderBy(l=>Vector3.Distance(l.transform.position,s.hero.transform.position)).First();yield return Go(material.SavePosition+Vector3.back*.8f);int before=s.hero.Inventory.Count(material.Kind);Check("real-material-pickup",material.PickUp(s.hero.Inventory)&&material.Collected&&s.hero.Inventory.Count(material.Kind)==before+material.Amount);Check("not-warehouse-precredit",s.Camp.Materials.All(v=>v==0),"synthetic fresh warehouse remains separate");
  string streams=JsonUtility.ToJson(s.Flow.ActiveRun.randomStreams),global=JsonUtility.ToJson(UnityEngine.Random.state);string a=JsonUtility.ToJson(new Eval{rows=RouteScoring.Evaluate(s)}),b=JsonUtility.ToJson(new Eval{rows=RouteScoring.Evaluate(s)});Check("routes-readonly-repeatable",a==b&&streams==JsonUtility.ToJson(s.Flow.ActiveRun.randomStreams)&&global==JsonUtility.ToJson(UnityEngine.Random.state));
  yield return Go(region.Layout.points[4].position+Vector3.left*5);yield return Shot("guardian-hall.png");Package();
 }
 [Serializable]class Eval{public RouteEvaluation[] rows;}
 IEnumerator Resume(){s.hero.SaveMenuOpen=true;var e=JsonUtility.FromJson<Expected>(File.ReadAllText(Root+"/expected.json"));Check("resume-same-run-instance-seed",s.Flow.ActiveRun.runId==e.run&&s.Flow.ActiveRun.regionInstanceId==e.region&&s.Flow.ActiveRun.seed==e.seed);Check("resume-layout",JsonUtility.ToJson(s.GetComponent<ForestRegionRuntime>().Layout)==e.layout);Check("resume-terrain-holes",TerrainSignature()==e.terrain);Check("resume-ledger-inventory",Ledger()==e.ledger&&InventorySignature()==e.inventory);Check("resume-all-event-flags",string.Join("|",s.Events.Points.OrderBy(p=>p.entityId).Select(p=>p.entityId+":"+p.Used))==e.events);Check("resume-streams",JsonUtility.ToJson(s.Flow.ActiveRun.randomStreams)==e.streams);Check("resume-gear-and-ground",GearSignature()==e.gear&&LootSignature()==e.loot);Check("resume-position",Vector3.Distance(s.hero.transform.position,e.position)<.15f);Check("resume-door-secret",s.GetComponent<RuinsExploration>().DoorOpen&&s.GetComponent<RuinsExploration>().SecretOpen);
  for(int i=0;i<3;i++){Check("actual-repeat-load-"+i,s.Saves.LoadProgress(false));s.hero.SaveMenuOpen=true;yield return null;Check("repeat-ground-unique-"+i,LootSignature()==e.loot&&GearSignature()==e.gear);Check("repeat-one-region-"+i,UnityEngine.Object.FindObjectsByType<RuinsExploration>().Count(r=>r.Active)==1);}s.hero.SaveMenuOpen=false;yield return null;FreezeOthers();yield return Go(s.GetComponent<ForestRegionRuntime>().Layout.exits[1].position);Check("extract-begin",s.Flow.BeginExtraction("c1:exit-hall"));s.Flow.CancelExtraction("controlled cancellation");Check("extract-cancel",s.Flow.ActiveRun.phase==RunPhase.Running);Check("extract-rebegin",s.Flow.BeginExtraction("c1:exit-hall"));yield return Wait(()=>s.Flow.HasResult,10);Check("actual-extracted-pending",s.Flow.HasResult&&s.Flow.Settlement.outcome==AdventureOutcome.Extracted);Check("settlement-commit",s.Flow.CommitSettlement());string profile=JsonUtility.ToJson(s.Flow.Profile);Check("settlement-no-repeat",s.Flow.CommitSettlement()&&profile==JsonUtility.ToJson(s.Flow.Profile));Check("settlement-ack",s.Flow.AcknowledgeSettlement());Check("camp-after-unload",s.Flow.AtCamp&&!s.GetComponent<ForestRegionRuntime>().Active);Check("reenter-new-run",s.Flow.DepartRuins()&&s.Flow.ActiveRun.runId!=e.run);Check("new-chest-not-old-identity",!Point("c1:hidden").Used);}
 IEnumerator Equip(GearType type,GearQuality q=GearQuality.White){s.hero.Inventory.SetOpen(false);var item=AdventureItems.New(type,q);var l=LootPickup.SpawnGear(item,s.hero.transform.position+Vector3.up*.7f);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(l.gameObject,s.gameObject.scene);yield return null;Check("equipment-real-pickup-"+type,l.PickUp(s.hero.Inventory));Check("equipment-real-main-"+type,s.hero.GetComponent<AdventureLoadout>().SelectMain(item));}
 IEnumerator Combat(GearType type,bool boss=false,bool die=false){
  if(!die)yield return Equip(type);yield return Depart();var enemy=s.enemies.Single(e=>e.entityId==(boss||die?"c1:guardian":"c1:guard"));FreezeOthers(enemy);
  if(boss||die){FreezeOthers();yield return Interact("c1:lever");yield return Interact("c1:door");yield return Go(new Vector3(8,.1f,280));enemy.enabled=true;enemy.GetComponent<RuinsBossBrain>().enabled=true;}
  var h=s.hero;var c=h.GetComponent<AdventureCombat>();var orbit=s.orbit;orbit.enabled=false;var cam=orbit.transform;var attacks=new HashSet<string>();bool phase2=false;float minimum=h.Health.Current;var brain=enemy.GetComponent<RuinsBossBrain>();if(brain!=null)brain.Observed+=t=>{File.AppendAllText(Root+"/boss-trace.jsonl",JsonUtility.ToJson(t)+"\n");if(t.stage=="release"){attacks.Add(t.attack);if(t.phase==2)phase2=true;}};
  enemy.Health.Observed+=o=>Trace("enemy-health",enemy.entityId,o.before,o.after);h.Health.Observed+=o=>Trace("hero-health",enemy.entityId,o.before,o.after);c.MeleeObserved+=o=>Trace("actual-melee-"+o.reason,o.target?.name,o.before,o.after);AdventureProjectile.Observed+=Projectile;
  float until=Time.realtimeSinceStartup+(die?110:boss?110:40);bool skill=false;string preDrop=null;enemy.Health.Observed+=o=>{if(o.before>0&&o.after<=0)preDrop=JsonUtility.ToJson(s.Flow.ActiveRun.randomStreams);};
  while(!enemy.Health.Dead&&!h.Health.Dead&&Time.realtimeSinceStartup<until){var delta=Vector3.ProjectOnPlane(enemy.transform.position-h.transform.position,Vector3.up);float range=type==GearType.Bow||type==GearType.Staff?6:type==GearType.Spear?2.2f:1.45f;bool telegraph=brain!=null&&brain.State==RuinsBossState.Telegraph;if(delta.sqrMagnitude>.01f)h.transform.rotation=Quaternion.LookRotation(delta);cam.position=h.transform.position+new Vector3(3,3,-5);cam.LookAt(enemy.transform.position+Vector3.up*1.1f);
   if(!die){if(delta.magnitude>range&&!telegraph)h.GetComponent<CharacterController>().Move(delta.normalized*h.moveSpeed*Time.deltaTime);if(telegraph&&brain.Remaining<.18f)h.Dodge.TryDodge(Vector3.Cross(Vector3.up,delta.normalized));bool observe=boss&&enemy.Health.Current<=enemy.Health.maxHealth*.5f&&(!phase2||!attacks.Contains("SealPulse"));if(!observe&&!telegraph&&delta.magnitude<range+.6f){if(!boss&&!skill){skill=c.UseSkill();}else c.Strike();}}
   else if(delta.magnitude>1.4f)h.GetComponent<CharacterController>().Move(delta.normalized*h.moveSpeed*Time.deltaTime);
   minimum=Mathf.Min(minimum,h.Health.Current);if(Time.frameCount%15==0)Trace("combat-frame",enemy.entityId,from:enemy.transform.position);yield return null;
  }
  AdventureProjectile.Observed-=Projectile;
  if(die){Check("actual-boss-killed-player",h.Health.Dead&&minimum==0);yield return Wait(()=>s.Flow.HasResult,3);Check("actual-death-pending",s.Flow.HasResult&&s.Flow.Settlement.outcome==AdventureOutcome.Death);Check("death-commit",s.Flow.CommitSettlement());Check("death-ack",s.Flow.AcknowledgeSettlement());Check("death-reopen",s.Flow.DepartRuins()&&s.WorldReady);yield break;}
  Check("actual-enemy-defeat-"+type,enemy.Health.Dead,"no damage or HP injection");if(boss){Check("boss-two-phases",phase2);Check("boss-distinct-attacks",attacks.Count>=2&&attacks.Contains("SealPulse"));Check("boss-immune",!(enemy.GetComponent<EnemyWeaponControl>()??enemy.gameObject.AddComponent<EnemyWeaponControl>()).Pull(h,1));}
  if(enemy.Health.Dead){enemy.DropLootOnce();var signature=LootSignature();enemy.DropLootOnce();Check("death-reward-unique",signature==LootSignature());Check("new-reward-old-streams",preDrop==JsonUtility.ToJson(s.Flow.ActiveRun.randomStreams));Check("death-drops-on-ground",UnityEngine.Object.FindObjectsByType<LootPickup>().Any(l=>!l.Collected));Check("death-save",s.Saves.SaveProgress(false));}
  yield return Shot("combat-"+type+".png");
 }
 void Projectile(AdventureProjectile.Observation o){Trace("projectile-"+o.stage,o.collider?.name,from:o.from,to:o.to);}
 IEnumerator Run(){yield return Entry();if(mode=="resume"){yield return Resume();yield break;}if(mode.StartsWith("combat-")){yield return Combat((GearType)int.Parse(mode.Substring(7)));yield break;}if(mode=="boss"){yield return Combat(GearType.Sword,true);yield break;}if(mode=="death"){yield return Combat(GearType.Sword,false,true);yield break;}yield return Depart();yield return Explore();}
 void Finish(string error){if(error!=null)Check("exception",false,error);Code=rows.Any(r=>r.status=="FAIL")?1:0;File.WriteAllText(Root+"/probe.json",JsonUtility.ToJson(new Report{layer=Application.isEditor?"controlled Editor":"isolated nondevelopment Player",mode=mode,error=error,rows=rows.ToArray()},true));Done=true;if(!Application.isEditor)Application.Quit(Code);}
}
